sections.code:
# Memeriksa status kategori umur seseorang
umur = 18

if umur >= 18:
    print("Status: Dewasa")
else:
    print("Status: Anak-anak")

# Mengelompokkan predikat nilai secara otomatis
nilai = 85

if nilai >= 90:
    print("Kategori: A")
elif nilai >= 75:
    print("Kategori: B")
else:
    print("Kategori: C")

# Otomatis menyaring nilai yang duplikat
angka = {1, 2, 2, 3}
print(angka)

# Operasi Himpunan
A = {1, 2, 3}
B = {3, 4, 5}

# Union (Gabungan seluruh elemen)
print(A.union(B))

# Intersection (Irisan elemen yang sama)
print(A.intersection(B))

# Output:
# {1, 2, 3}
# {1, 2, 3, 4, 5}
# {3}

