# Penanganan Error Sederhana
try:
    # Mencoba konversi string teks biasa menjadi integer
    angka = int("abc")
except:
    print("Terjadi error: Input tidak valid!")

# Menangkap Jenis Exception Tertentu
try:
    x = int("abc")
except ValueError:
    print("Terjadi error: Gagal konversi teks ke angka (ValueError).")
except ZeroDivisionError:
    print("Terjadi error: Pembagian dengan nol tidak diperbolehkan!")

# Output:
# Terjadi error: Input tidak valid!
# Terjadi error: Gagal konversi teks ke angka (ValueError).
